import calipy as cp
from calipy.graph import ConstantValue

reading = cp.dim('reading', size=8, description='Independent repeated measurements of one shared mean.')

scale_a = ConstantValue(0.2, name='scale_a')
scale_a._calipy_authoring_id = 'scale_a'

mu = cp.LatentParameter(name='mu', init=2, prior_radius=5)
mu._calipy_authoring_id = 'mu'
measurement_a = cp.effects.NoiseAddition(name='measurement_a', batch_dims=reading)
measurement_a._calipy_authoring_id = 'measurement_a'

@cp.block(name='first_measurement')
def model():
    mu._calipy_authoring_id = 'mu'
    mu__value = mu()
    measurement_a._calipy_authoring_id = 'measurement_a'
    measurement_a__sample = measurement_a(mean=mu__value, standard_deviation=scale_a)
    return {
        'measurement_a': measurement_a__sample,
    }

